package io.github.ningpp.compat;

/**
 * Replacement for {@code System.Numerics.Complex} (generated by CSharpToJava converter).
 * <p>
 * Provides an immutable complex-number value type with the static operator methods
 * ({@link #add}, {@link #subtract}, {@link #multiply}, {@link #divide},
 * {@link #negate}, {@link #pow}) and the read-only {@link #Zero} constant used by
 * converted C# code that referenced {@code System.Numerics.Complex} via a using
 * alias (e.g. {@code using NumComplex = System.Numerics.Complex;}).
 * <p>
 * The arithmetic semantics mirror the .NET {@code System.Numerics.Complex} type:
 * <ul>
 *   <li>{@code add(a, b)} = a + b</li>
 *   <li>{@code subtract(a, b)} = a - b</li>
 *   <li>{@code multiply(a, b)} = a * b</li>
 *   <li>{@code multiply(d, b)} = d * b (scalar left)</li>
 *   <li>{@code divide(a, d)} = a / d (scalar right, d is double)</li>
 *   <li>{@code divide(a, b)} = a / b</li>
 *   <li>{@code negate(a)} = -a</li>
 *   <li>{@code pow(a, power)} = a^power (De Moivre / polar form)</li>
 * </ul>
 */
public final class Complex {
    private final double real;
    private final double imaginary;

    /** Mirrors {@code System.Numerics.Complex.Zero} — the complex value (0, 0). */
    public static final Complex Zero = new Complex(0.0, 0.0);

    /** Mirrors {@code System.Numerics.Complex.One} — the complex value (1, 0). */
    public static final Complex One = new Complex(1.0, 0.0);

    /** Mirrors {@code System.Numerics.Complex.ImaginaryOne} — the complex value (0, 1). */
    public static final Complex ImaginaryOne = new Complex(0.0, 1.0);

    /**
     * Mirrors {@code new System.Numerics.Complex(double, double)}.
     *
     * @param real      the real part
     * @param imaginary the imaginary part
     */
    public Complex(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    /** Mirrors {@code System.Numerics.Complex.Real} property. */
    public double getReal() {
        return real;
    }

    /** Mirrors {@code System.Numerics.Complex.Imaginary} property. */
    public double getImaginary() {
        return imaginary;
    }

    /** Mirrors {@code System.Numerics.Complex.Magnitude} property (modulus). */
    public double getMagnitude() {
        return Math.sqrt(real * real + imaginary * imaginary);
    }

    /** Mirrors {@code System.Numerics.Complex.Phase} property (argument in radians). */
    public double getPhase() {
        return Math.atan2(imaginary, real);
    }

    // ─── Static operator methods (emitted by the converter for C# operators) ───

    /**
     * Mirrors {@code operator+} — returns {@code left + right}.
     *
     * @param left  the left operand
     * @param right the right operand
     * @return the sum
     */
    public static Complex add(Complex left, Complex right) {
        return new Complex(
            left.real + right.real,
            left.imaginary + right.imaginary);
    }

    /**
     * Mirrors {@code operator-} — returns {@code left - right}.
     *
     * @param left  the left operand
     * @param right the right operand
     * @return the difference
     */
    public static Complex subtract(Complex left, Complex right) {
        return new Complex(
            left.real - right.real,
            left.imaginary - right.imaginary);
    }

    /**
     * Mirrors {@code operator*} — returns {@code left * right}.
     *
     * @param left  the left operand
     * @param right the right operand
     * @return the product
     */
    public static Complex multiply(Complex left, Complex right) {
        return new Complex(
            left.real * right.real - left.imaginary * right.imaginary,
            left.real * right.imaginary + left.imaginary * right.real);
    }

    /**
     * Scalar multiplication — {@code scalar * value}.
     * Used by converted code like {@code Complex.multiply(2.0, c)}.
     *
     * @param scalar the scalar (double)
     * @param value  the complex value
     * @return the scalar product
     */
    public static Complex multiply(double scalar, Complex value) {
        return new Complex(
            scalar * value.real,
            scalar * value.imaginary);
    }

    /**
     * Scalar multiplication — {@code value * scalar}.
     *
     * @param value  the complex value
     * @param scalar the scalar (double)
     * @return the scalar product
     */
    public static Complex multiply(Complex value, double scalar) {
        return multiply(scalar, value);
    }

    /**
     * Mirrors {@code operator/} — returns {@code left / right}.
     *
     * @param left  the left operand
     * @param right the right operand
     * @return the quotient
     */
    public static Complex divide(Complex left, Complex right) {
        // a / b = (a * conj(b)) / |b|^2
        double denom = right.real * right.real + right.imaginary * right.imaginary;
        if (denom == 0.0) {
            // Division by zero: .NET returns Complex(Infinity, Infinity) or NaN.
            // Match .NET semantics (real=NaN, imag=NaN when 0/0; otherwise Infinity).
            return new Complex(
                left.real == 0.0 && right.real == 0.0 && right.imaginary == 0.0
                    ? Double.NaN : left.real / 0.0,
                left.imaginary == 0.0 && right.real == 0.0 && right.imaginary == 0.0
                    ? Double.NaN : left.imaginary / 0.0);
        }
        return new Complex(
            (left.real * right.real + left.imaginary * right.imaginary) / denom,
            (left.imaginary * right.real - left.real * right.imaginary) / denom);
    }

    /**
     * Scalar division — {@code value / scalar}.
     * Used by converted code like {@code Complex.divide(c, 2)}.
     *
     * @param value  the complex value
     * @param scalar the scalar divisor (double)
     * @return the quotient
     */
    public static Complex divide(Complex value, double scalar) {
        return new Complex(
            value.real / scalar,
            value.imaginary / scalar);
    }

    /**
     * Mirrors {@code operator- (unary)} — returns {@code -value}.
     *
     * @param value the operand
     * @return the negation
     */
    public static Complex negate(Complex value) {
        return new Complex(-value.real, -value.imaginary);
    }

    /**
     * Mirrors {@code System.Numerics.Complex.Pow(Complex, double)}.
     * Computes {@code base}^{@code power} using polar form (De Moivre's theorem).
     *
     * @param base  the base
     * @param power the exponent
     * @return the result of raising {@code base} to the {@code power}
     */
    public static Complex pow(Complex base, double power) {
        // Special case: base == Zero
        if (base.real == 0.0 && base.imaginary == 0.0) {
            if (power > 0.0) return Zero;
            if (power == 0.0) return One;
            // negative power of zero → Infinity
            return new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        }

        // Use polar form: base = r * e^(iθ), base^power = r^power * e^(i*power*θ)
        double r = Math.sqrt(base.real * base.real + base.imaginary * base.imaginary);
        double theta = Math.atan2(base.imaginary, base.real);

        double newR = Math.pow(r, power);
        double newTheta = power * theta;

        return new Complex(
            newR * Math.cos(newTheta),
            newR * Math.sin(newTheta));
    }

    /**
     * Mirrors {@code System.Numerics.Complex.Pow(Complex, Complex)}.
     *
     * @param base     the base
     * @param exponent the exponent (complex)
     * @return the result
     */
    public static Complex pow(Complex base, Complex exponent) {
        // base^exp = exp(exp * log(base))
        // log(base) = ln|base| + i*arg(base)
        double r = Math.sqrt(base.real * base.real + base.imaginary * base.imaginary);
        double theta = Math.atan2(base.imaginary, base.real);

        if (r == 0.0) {
            // log(0) = -Infinity
            return Zero;
        }

        double logR = Math.log(r);
        // expReal = ln|base|, expImag = arg(base)
        // exp * log(base) = (expReal*lnR - expImag*theta) + i*(expReal*theta + expImag*lnR)
        double productReal = exponent.real * logR - exponent.imaginary * theta;
        double productImag = exponent.real * theta + exponent.imaginary * logR;

        // exp(product) = e^(productReal) * (cos(productImag) + i*sin(productImag))
        double expReal = Math.exp(productReal);
        return new Complex(
            expReal * Math.cos(productImag),
            expReal * Math.sin(productImag));
    }

    /**
     * Mirrors {@code System.Numerics.Complex.FromPolarCoordinates}.
     *
     * @param magnitude the magnitude
     * @param phase     the phase in radians
     * @return the complex number
     */
    public static Complex fromPolarCoordinates(double magnitude, double phase) {
        return new Complex(
            magnitude * Math.cos(phase),
            magnitude * Math.sin(phase));
    }

    /**
     * Mirrors {@code System.Numerics.Complex.Conjugate}.
     *
     * @param value the value
     * @return the complex conjugate
     */
    public static Complex conjugate(Complex value) {
        return new Complex(value.real, -value.imaginary);
    }

    /**
     * Mirrors {@code System.Numerics.Complex.Reciprocal}.
     *
     * @param value the value
     * @return the reciprocal (1/value)
     */
    public static Complex reciprocal(Complex value) {
        return divide(One, value);
    }

    /**
     * Mirrors {@code System.Numerics.Complex.Abs} — the magnitude (modulus).
     *
     * @param value the value
     * @return the absolute value (magnitude)
     */
    public static double abs(Complex value) {
        return value.getMagnitude();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Complex other)) return false;
        return this.real == other.real && this.imaginary == other.imaginary;
    }

    @Override
    public int hashCode() {
        return Double.hashCode(real) * 31 + Double.hashCode(imaginary);
    }

    @Override
    public String toString() {
        if (Double.isNaN(real) || Double.isNaN(imaginary)) return "NaN";
        if (imaginary == 0.0) return Double.toString(real);
        if (real == 0.0) return imaginary + "i";
        return real + (imaginary > 0 ? "+" : "") + imaginary + "i";
    }
}
